styles.css:
@font-face{font-family:"Noto Sans KR";src:url("assets/fonts/NotoSansKR.ttf") format("truetype");font-weight:100 900;font-style:normal;font-display:swap;}
*{box-sizing:border-box}body{margin:0;background:#fff;color:#111;font:500 14px/1.5 "Noto Sans KR",sans-serif}button,input{font:inherit}button:disabled,input:disabled{opacity:1}h1,h2,p{margin:0}img{display:block}.frame{max-width:430px;margin:auto;padding:0 24px 24px;--ink:#111;--muted:#666;--border:#e8e8e8}.tabs-slot{margin-top:26px}.days-slot{margin-top:26px}.footer-slot{margin-top:24px}.disclosure{margin-top:16px;color:#666}button:focus-visible,input:focus-visible{outline:2px solid #111;outline-offset:3px}@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important}} #itinerary-layout :is(#place1,#place2,#place3){display:grid;grid-template-columns:22px minmax(0,1fr);gap:9px;align-items:center}#itinerary-layout :is(#place1-card,#place2-card,#place3-card){display:flex;align-items:center;min-width:0;min-height:96px;height:auto;gap:0}#itinerary-layout :is(#place1-photo,#place2-photo,#place3-photo){width:96px;height:96px;flex:0 0 96px;object-fit:cover}#itinerary-layout .place-copy{min-width:0;flex:1;padding:8px 12px;overflow-wrap:anywhere}#itinerary-layout .place-grip{width:18px;height:18px;flex:0 0 18px;margin-right:6px}@media(max-width:360px){#itinerary-layout :is(#place1-photo,#place2-photo,#place3-photo){width:72px;height:72px;flex-basis:72px}#itinerary-layout .place-copy{padding:8px}}
[data-ui-unit="E1"].trip-header {
  display: flex;
  align-items: center;
  min-height: 62px;
}

[data-ui-unit="E1"].trip-header > button,
[data-ui-unit="E1"].trip-header > span {
  flex: 0 0 44px;
  display: flex;
  align-items: center;
  justify-content: center;
}

[data-ui-unit="E1"].trip-header > h1 {
  flex: 1 1 auto;
  min-width: 0;
  text-align: center;
  font-size: 18px;
  line-height: 26px;
  font-weight: 700;
  margin: 0;
  overflow-wrap: break-word;
}

[data-ui-unit="E1"].trip-header button {
  background: transparent;
  border: none;
  padding: 0;
  width: 44px;
  height: 44px;
  cursor: default;
}

[data-ui-unit="E1"].trip-header button img {
  width: 24px;
  height: 24px;
  display: block;
}

[data-ui-unit="E1"].trip-header button:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
[data-ui-unit="E2"].day-tabs {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 8px;
}

[data-ui-unit="E2"].day-tabs button {
  font: 700 14px/1 "Noto Sans KR", sans-serif;
  padding: 8px 16px;
  min-width: 64px;
  min-height: 32px;
  height: auto;
  border-radius: 16px;
  border: 1px solid #e8e8e8;
  background-color: #fff;
  color: #111;
  cursor: default;
  white-space: nowrap;
  margin: 0;
}

[data-ui-unit="E2"].day-tabs button[aria-pressed="true"] {
  background-color: #111;
  color: #fff;
  border-color: #111;
}

[data-ui-unit="E2"].day-tabs button:disabled {
  opacity: 1;
}
#itinerary-layout{display:grid;gap:40px}
[data-ui-unit="E3A"].day-group h2 {
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
  margin: 0;
}

[data-ui-unit="E3A"].day-group span {
  font-weight: 500;
  color: var(--muted, #666);
}

[data-ui-unit="E3A"] .place-row {
  margin-top: 16px;
}

[data-ui-unit="E3A"] .place-card {
  border: 1px solid var(--border, #e8e8e8);
  border-radius: 6px;
}

[data-ui-unit="E3A"] .place-title {
  font-size: 14px;
  line-height: 1.4;
  font-weight: 700;
}

[data-ui-unit="E3A"] .place-type {
  font-size: 14px;
  line-height: 1.4;
  font-weight: 500;
  color: var(--muted, #666);
}
[data-ui-unit="E3B"] > h2 {
  font-size: 16px;
  font-weight: 700;
  line-height: 1.4;
  margin: 0;
}
[data-ui-unit="E3B"] > h2 span {
  font-weight: 500;
  color: var(--muted, #666);
}
[data-ui-unit="E3B"] > .place-row:first-of-type {
  margin-top: 16px;
}
[data-ui-unit="E3B"] > .place-row:not(:first-of-type) {
  margin-top: 18px;
}
[data-ui-unit="E3B"] .place-card {
  border: 1px solid var(--border, #e8e8e8);
  border-radius: 6px;
}
[data-ui-unit="E3B"] .place-title {
  font-weight: 700;
  font-size: 14px;
  line-height: 1.4;
}
[data-ui-unit="E3B"] .place-region {
  font-weight: 700;
  font-size: 14px;
  line-height: 1.4;
  margin-top: 2px;
}
[data-ui-unit="E3B"] .place-type {
  font-weight: 500;
  color: var(--muted, #666);
  font-size: 14px;
  line-height: 1.4;
  margin-top: 2px;
}
[data-ui-unit="E3C"] > h2 {
  font-size: 16px;
  line-height: 1.4;
  font-weight: 700;
  margin-bottom: 16px;
}

[data-ui-unit="E3C"] > h2 span {
  font-weight: 500;
  color: var(--muted, #666);
}

[data-ui-unit="E3C"] .partial-slot {
  margin-left: 31px;
  height: 18px;
  overflow: hidden;
}

[data-ui-unit="E3C"] .partial-card {
  border: 1px solid var(--border, #e8e8e8);
  border-radius: 6px;
  height: 100%;
  display: flex;
  align-items: flex-start;
}

[data-ui-unit="E3C"] .partial-card img {
  width: 96px;
  height: 17px;
  display: block;
  object-fit: cover;
}

@media (max-width: 360px) {
  [data-ui-unit="E3C"] .partial-card img {
    width: 72px;
  }
}
[data-ui-unit="E4"] {
  width: 100%;
}
[data-ui-unit="E4"].trip-footer {
  display: flex;
  justify-content: center;
  width: 100%;
}
[data-ui-unit="E4"] button {
  display: block;
  width: 100%;
  min-height: 56px;
  border-radius: 12px;
  background-color: #bdbdbd;
  color: #fff;
  font-size: 16px;
  font-weight: 700;
  line-height: 1.2;
  border: none;
  padding: 0;
}
[data-ui-unit="E4"] button:disabled {
  background-color: #bdbdbd;
  color: #fff;
  opacity: 1;
  cursor: not-allowed;
}
